import React from 'react';
import '../styles/Messages.css';

function Messages() {
  const chats = [
    { id: 1, user: 'Артём Топалян', lastMessage: 'Я была неправа', date: '27.12.2021' },
    { id: 2, user: 'riddleforcop', lastMessage: 'Напишите первым!', date: null },
    { id: 3, user: 'Валерия Колмогорова', lastMessage: 'А он хайповый парень', date: '27.12.2021' },
    { id: 4, user: 'Юрий Сёмин', lastMessage: 'Напишите первым!', date: null },
  ];

  return (
    <div className="messages-page">
      {chats.map(chat => (
        <div key={chat.id} className="chat-item">
          <h4 className="chat-user">{chat.user}</h4>
          <p className="chat-last-message">
            {chat.lastMessage} {chat.date && <span className="chat-date">({chat.date})</span>}
          </p>
        </div>
      ))}
    </div>
  );
}

export default Messages;
